/// `api.server`.
#[derive(Clone, Copy)]
pub struct ServerApi<'a>(pub(crate) &'a Client);

impl<'a> ServerApi<'a> {
    /// `server.info(input?, requestOptions?)`
    pub fn info(self, input: &Json, options: RequestOptions) -> Call {
        self.0.call(&SERVER_INFO, input, options)
    }

    /// `server.pair(input?, requestOptions?)`
    pub fn pair(self, input: &Json, options: RequestOptions) -> Call {
        self.0.call(&SERVER_PAIR, input, options)
    }

    /// `server.connect(input, requestOptions?)`
    pub fn connect(self, input: &Json, options: RequestOptions) -> Call {
        self.0.call(&SERVER_CONNECT, input, options)
    }
}

